export const categoryById = (id) => VISUAL_CATEGORIES.find((c) => c.id === id) || null

export const machinesInCategory = (id) => MACHINES.filter((m) => m.visualCategory === id)

export const machineById = (id) => MACHINES.find((m) => m.id === id) || null

/* Special Applications is grouped by its official subcategory so the reader sees
   Demolition / Forestry / Tunnelling rather than one flat list of base codes. */
export const groupsInCategory = (id) => {
  const list = machinesInCategory(id)
  if (id !== 'special') return [{ label: null, machines: list }]
  const order = [
    'Demolition Excavators',
    'Super Long Front Excavators',
    'Clamshell Telescopic Arm Excavators',
    'Forestry Excavators',
    'Tunnelling Excavators',
    'Amphibious Excavators',
  ]
  return order
    .map((sub) => ({ label: sub, machines: list.filter((m) => m.subcategory === sub) }))
    .filter((g) => g.machines.length > 0)
}
